(6383892, 944874, 96751, '<td valign="top">Love those old boxes!</td>', 'Love those old boxes!', '2011-04-12 16:36:44.000000', NULL, 1),
(6383895, 944867, 96751, '<td valign="top">Ribbon.  Easily.  Not only a fabulous image, but the craftsmanship and execution is outstanding.  Fun, wonderful shot.</td>', 'Ribbon.  Easily.  Not only a fabulous image, but the craftsmanship and execution is outstanding.  Fun, wonderful shot.', '2011-04-12 16:38:19.000000', NULL, 1),
(6383918, 944867, 61961, '<td valign="top">Sometimes one must decide if one is voting on the photo or the construction, so in this case it is a pleasure that both are good (though I might prefer to see the fish angled towards the camera rather than away)!  Very nice color and light.</td>', 'Sometimes one must decide if one is voting on the photo or the construction, so in this case it is a pleasure that both are good (though I might prefer to see the fish angled towards the camera rather than away)!  Very nice color and light.', '2011-04-12 16:56:16.000000', NULL, 1),
(6383920, 944829, 61961, '<td valign="top">Excellent clarity.  Squirrel shots don''t typically grab me but this one''s connection to the challenge theme does!</td>', 'Excellent clarity.  Squirrel shots don''t typically grab me but this one''s connection to the challenge theme does!', '2011-04-12 16:59:14.000000', NULL, 1),
